        if (name.endsWith("Left")) return name.substring(0, name.length() - 4) + "Start";
        if (name.endsWith("Right")) return name.substring(0, name.length() - 5) + "End";
        return name;
    }

    public static String convertNewToOld(String name) {
        if (name.endsWith("Start")) return name.substring(0, name.length() - 5) + "Left";
        if (name.endsWith("End")) return name.substring(0, name.length() - 3) + "Right";
        return name;
    }

    public static String convertToOppositeDirection(String name) {
        if (name.endsWith("Left")) return name.substring(0, name.length() - 4) + "Right";
        if (name.endsWith("Right")) return name.substring(0, name.length() - 5) + "Left";
        if (name.endsWith("Start")) return name.substring(0, name.length() - 5) + "End";
        if (name.endsWith("End")) return name.substring(0, name.length() - 3) + "Start";
        return name;
    }

