            String qualifiers = name.substring(dash + 1);
            int vIndex = qualifiers.indexOf('v');
            if (vIndex != -1) {
                try {
                    return Integer.parseInt(qualifiers.substring(vIndex + 1));
                } catch (NumberFormatException e) {
                    // ignore
                }
            }
        }
        return 1;
    }
}
