import com.android.tools.lint.detector.api.XmlScanner;
import org.w3c.dom.Attr;
import org.w3c.dom.Element;

import java.util.Collection;
import java.util.Collections;

public class RtlDetector extends Detector implements XmlScanner {
    public static final Issue ISSUE = Issue.create(
        "RtlCompat",
        "Right-to-left text compatibility issues",
        "API 17 adds a `textAlignment` attribute to specify text alignment. However, " +
        "if you are supporting older versions than API 17, you must **also** specify a " +
        "gravity or layout_gravity attribute, since older platforms will ignore the " +
        "`textAlignment` attribute.",
        Category.CORRECTNESS,
        6,
        Severity.WARNING,
        new Implementation(RtlDetector.class, Scope.RESOURCE_FILE_SCOPE));

    private static final int RTL_VIEW_API = 17;
    private static final int RTL_GRAVITY_API = 14;

    @Override
    public Collection<String> getApplicableAttributes() {
        return null; // Visit all attributes
    }

    @Override
    public void visitAttribute(XmlContext context, Attr attribute) {
        if (!SdkConstants.ANDROID_URI.equals(attribute.getNamespaceURI())) {
            return;
        }

        String name = attribute.getLocalName();
        int minSdk = context.getMainProject().getMinSdk();
        Element element = attribute.getOwnerElement();

        // Check textAlignment
        if (name.equals(SdkConstants.ATTR_TEXT_ALIGNMENT)) {
            if (minSdk < RTL_VIEW_API) {
                boolean hasGravity = element.hasAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_GRAVITY);
                boolean hasLayoutGravity = element.hasAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_LAYOUT_GRAVITY);
                if (!hasGravity && !hasLayoutGravity) {
                    context.report(ISSUE, context.getLocation(attribute),
                        "Consider adding `android:gravity` or `android:layout_gravity` for compatibility with API < 17");
                }
            }
            return;
        }

        // Check Start/End attributes
        if (name.endsWith("Start") || name.endsWith("End")) {
            if (minSdk < RTL_VIEW_API) {
                String fallback = name.endsWith("Start")
                    ? name.substring(0, name.length() - 5) + "Left"
                    : name.substring(0, name.length() - 3) + "Right";
                if (!element.hasAttributeNS(SdkConstants.ANDROID_URI, fallback)) {
                    context.report(ISSUE, context.getLocation(attribute),
                        "Consider adding `android:" + fallback + "` for compatibility with API < 17");
                }
            }
            return;
        }

        // Check gravity/layout_gravity values
        if (name.equals(SdkConstants.ATTR_GRAVITY) || name.equals(SdkConstants.ATTR_LAYOUT_GRAVITY)) {
            if (minSdk < RTL_GRAVITY_API) {
                String value = attribute.getValue();
                if (value.contains("start") && !value.contains("left")) {
                    context.report(ISSUE, context.getLocation(attribute),
                        "Consider adding `left` to `android:" + name + "` for compatibility with API < 14");
                } else if (value.contains("end") && !value.contains("right")) {
                    context.report(ISSUE, context.getLocation(attribute),
                        "Consider adding `right` to `android:" + name + "` for compatibility with API < 14");
                }
            }
        }
    }
}
